create table suppliers(id uuid primary key default gen_random_uuid(),organisation_id uuid not null references organisations(id),name text not null,email text,phone text,active boolean not null default true,created_at timestamptz not null default now(),unique(organisation_id,id),unique(organisation_id,name));
create table purchase_orders(id uuid primary key default gen_random_uuid(),organisation_id uuid not null references organisations(id),supplier_id uuid not null,location_id uuid not null,status text not null default 'draft' check(status in('draft','sent','part_received','completed','cancelled')),expected_at date,reference text,created_by uuid not null references users(id),created_at timestamptz not null default now(),foreign key(organisation_id,supplier_id) references suppliers(organisation_id,id),foreign key(organisation_id,location_id) references locations(organisation_id,id),unique(organisation_id,id));
create table purchase_order_items(id uuid primary key default gen_random_uuid(),organisation_id uuid not null references organisations(id),purchase_order_id uuid not null,variant_id uuid not null,ordered_quantity numeric(12,3) not null check(ordered_quantity>0),received_quantity numeric(12,3) not null default 0 check(received_quantity>=0),unit_cost numeric(12,2) not null check(unit_cost>=0),supplier_sku text,foreign key(organisation_id,purchase_order_id) references purchase_orders(organisation_id,id),foreign key(organisation_id,variant_id) references product_variants(organisation_id,id));
create index suppliers_org_idx on suppliers(organisation_id);create index po_org_idx on purchase_orders(organisation_id,created_at desc);create index poi_po_idx on purchase_order_items(purchase_order_id);
do $$ declare n text;begin foreach n in array array['suppliers','purchase_orders','purchase_order_items'] loop execute format('alter table %I enable row level security',n);execute format('alter table %I force row level security',n);execute format('create policy tenant_isolation on %I for all using(organisation_id=(select app_current_organisation_id())) with check(organisation_id=(select app_current_organisation_id()))',n);end loop;end $$;
grant select,insert,update on suppliers,purchase_orders,purchase_order_items to counter_app;
